def action_split_transfer(self):
    if self.state == 'done':
        return
    if all(m.uom_id.is_zero(m.quantity) for m in self.move_ids):
        raise UserError(_("%s: Nothing to split. Fill the quantities you want in a new transfer in the done quantities", self.display_name))
    if all(m.uom_id.compare(m.quantity, m.product_uom_qty) == 0 for m in self.move_ids):
        raise UserError(_("%s: Nothing to split, all demand is done. For split you need at least one line not fully fulfilled", self.display_name))
    if any(m.uom_id.compare(m.quantity, m.product_uom_qty) > 0 for m in self.move_ids):
        raise UserError(_("%s: Can't split: quantities done can't be above demand", self.display_name))

    moves = self.move_ids.filtered(lambda m: m.state not in ('done', 'cancel') and m.quantity != 0)
    backorder_moves = moves._create_backorder()
    backorder_moves += self.move_ids.filtered(lambda m: m.quantity == 0)
    backorder = self._create_backorder(backorder_moves=backorder_moves, from_manual_backorder=True)
    backorder.message_post(
        body=self.env._('Split from %(original_picking_link)s.', original_picking_link=self._get_html_link())
    )
    return {
        'name': self.env._('Split Backorder'),
        'type': 'ir.actions.act_window',
        'res_model': 'stock.picking',
        'view_mode': 'form',
        'res_id': backorder.id,
    }

class ShipmentCheckQuantity:
    "Check quantities per product between source and target moves"
    __slots__ = ()

    @property
    def _check_quantity_source_moves(self):
        raise NotImplementedError

    @property
    def _check_quantity_target_moves(self):
        raise NotImplementedError

    def check_quantity(self):
        pool = Pool()
        Warning = pool.get('res.user.warning')
        Lang = pool.get('ir.lang')
        lang = Lang.get()

        source_qties = defaultdict(float)
        for move in self._check_quantity_source_moves:
            source_qties[move.product] += move.internal_quantity

        target_qties = defaultdict(float)
        for move in self._check_quantity_target_moves:
            target_qties[move.product] += move.internal_quantity

        diffs = {}
        for product, incoming_qty in source_qties.items():
            unit = product.default_uom
            incoming_qty = unit.round(incoming_qty)
            inventory_qty = unit.round(target_qties.pop(product, 0))
            diff = inventory_qty - incoming_qty
            if diff:
                diffs[product] = diff
        diffs.update((k, v) for k, v in target_qties.items() if v)

def receive(cls, shipments):
    Move = Pool().get('stock.move')
    with Move.bulk_func('do', auto=False) as do:
        for shipment in shipments:
            do.extend(shipment.incoming_moves)
    with Move.bulk_delete(auto=False) as delete:
        for shipment in shipments:
            for move in shipment.inventory_moves:
                if move.state in {'draft', 'cancelled'}:
                    delete.push(move)
    cls.create_inventory_moves(shipments)
    # Set received state to allow done transition
    cls.write(shipments, {'state': 'received'})
    with cls.bulk_func('do', auto=False) as do:
        for shipment in shipments:
            if shipment.warehouse_storage == shipment.warehouse_input:
                do.push(shipment)

