@classmethod
@ModelView.button
@Workflow.transition('failed')
@reset_employee('passed_by')
@set_employee('failed_by')
def fail(cls, inspections):
    pool = Pool()
    Alert = pool.get('quality.alert')
    alerts = []
    for inspection in inspections:
        if not inspection.alerts:
            alerts.append(inspection.get_alert())
    Alert.save(alerts)

protected void planStockMove(StockMove stockMove, boolean splitByTrackingNumber)
    throws AxelorException {
  if (stockMove.getStatusSelect() == null
      || stockMove.getStatusSelect() != StockMoveRepository.STATUS_DRAFT) {
    throw new AxelorException(
        stockMove,
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(StockExceptionMessage.STOCK_MOVE_PLAN_WRONG_STATUS));
  }

  LOG.debug("Stock move planification : {} ", stockMove.getStockMoveSeq());

  // This call will split move line by tracking number
  // But only works if the line has not been already splited
  if (splitByTrackingNumber) {
    stockMoveLineService.splitStockMoveLineByTrackingNumber(stockMove);
  }

  stockMove = JpaModelHelper.ensureManaged(stockMove);
  String draftSeq;

  // Set the sequence.
  if (Beans.get(SequenceService.class)
      .isEmptyOrDraftSequenceNumber(stockMove.getStockMoveSeq())) {
    draftSeq = stockMove.getStockMoveSeq();
    stockMove.setStockMoveSeq(
        stockMoveToolService.getSequenceStockMove(
            stockMove.getTypeSelect(), stockMove.getCompany(), stockMove));
  } else {
    draftSeq = null;
  }

  if (Strings.isNullOrEmpty(stockMove.getName())
      || draftSeq != null && stockMove.getName().startsWith(draftSeq)) {
    stockMove.setName(stockMoveToolService.computeName(stockMove));
  }

  int initialStatus = stockMove.getStatusSelect();

  setPlannedStatus(stockMove);

  updateLocations(stockMove, initialStatus);
  stockMove = JpaModelHelper.ensureManaged(stockMove);
  stockMove.setCancelReason(null);
  stockMove.setRealDate(null);

  stockMove.setExTaxTotal(stockMoveToolService.compute(stockMove));

  stockMoveRepo.save(stockMove);

protected String realizeStockMove(StockMove stockMove, boolean checkOngoingInventoryFlag)
    throws AxelorException {
  if (stockMove.getStatusSelect() == null
      || stockMove.getStatusSelect() != StockMoveRepository.STATUS_PLANNED) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(StockExceptionMessage.STOCK_MOVE_REALIZATION_WRONG_STATUS));
  }

  LOG.debug("Stock realization : {} ", stockMove.getStockMoveSeq());

  if (stockMove.getTypeSelect() == StockMoveRepository.TYPE_INCOMING
      && !stockMove.getIsReversion()
      && appStockService.getAppStock().getIsRequiredShipmentSupplierDetails()
      && (stockMove.getSupplierShipmentDate() == null
          || Strings.isNullOrEmpty(stockMove.getSupplierShipmentRef()))) {
    throw new AxelorException(
        stockMove,
        TraceBackRepository.CATEGORY_MISSING_FIELD,
        I18n.get(StockExceptionMessage.STOCK_MOVE_MISSING_SUPPLIER_SHIPMENT_DETAILS));
  }

  if (checkOngoingInventoryFlag) {
    checkOngoingInventory(stockMove);
  }

  int initialStatus = stockMove.getStatusSelect();

  String newStockSeq = null;
  stockMoveLineService.checkTrackingNumber(stockMove);
  stockMoveLineService.checkConformitySelection(stockMove);
  fillRealizeWapPriceForStockMove(stockMove);

  stockMoveLineService.checkExpirationDates(stockMove);

  BigDecimal exTaxTotal = stockMoveToolService.compute(stockMove);
  stockMove = JpaModelHelper.ensureManaged(stockMove);
  setRealizedStatus(stockMove);
  stockMove.setRealDate(appBaseService.getTodayDate(stockMove.getCompany()));
  stockMove.setExTaxTotal(exTaxTotal);

  stockMove = stockMoveRepo.save(stockMove);

  stockMoveLineService.updateLocations(
      initialStatus,
      StockMoveRepository.STATUS_CANCELED,
      getPlannedStockMoveLineIds(stockMove, true),
      stockMove.getEstimatedDate(),
      false,
      false,
      true);

  stockMoveLineService.updateLocations(
      StockMoveRepository.STATUS_DRAFT,
      StockMoveRepository.STATUS_REALIZED,
      getStockMoveLineIds(stockMove),
      stockMove.getEstimatedDate(),
      true,
      true,
      true);

  stockMove = JpaModelHelper.ensureManaged(stockMove);
  clearPlannedStockMoveLine(stockMove, true);
  storeCustomsCodesForStockMove(stockMove);

public void preFillOperations(QualityControl qualityControl, QualityProcess process)
    throws AxelorException {

  List<ControlPointModel> controlPointModelList = process.getControlPointModelList();
  List<ControlPointModel> optionalControlPointModelList =
      process.getOptionalControlPointModelList();
  List<QualityCorrectiveAction> qualityCorrectiveActionList =
      process.getQualityCorrectiveActionList();

  if (controlPointModelList != null) {
    qualityControl.getControlPointList().clear();

    for (ControlPointModel model : controlPointModelList) {
      ControlPoint point = new ControlPoint();
      this.createControlPointListItem(model, point, qualityControl);
      qualityControl.addControlPointListItem(point);
    }
  }

  if (optionalControlPointModelList != null) {
    qualityControl.getOptionalControlPointList().clear();

    for (ControlPointModel model : optionalControlPointModelList) {
      ControlPoint point = new ControlPoint();
      this.createControlPointListItem(model, point, qualityControl);
      qualityControl.addOptionalControlPointListItem(point);
    }
  }

  if (qualityCorrectiveActionList != null) {
    qualityControl.getQualityCorrectiveActionList().clear();

    for (QualityCorrectiveAction qualityCorrectiveAction : qualityCorrectiveActionList) {
      qualityCorrectiveAction =
          Beans.get(QualityCorrectiveActionRepository.class).copy(qualityCorrectiveAction, true);
      qualityControl.addQualityCorrectiveActionListItem(qualityCorrectiveAction);
    }
  }
}

@Transactional
public void createControlPointListItem(
    ControlPointModel model, ControlPoint point, QualityControl qualityControl) {

  point.setStatusSelect(ControlPointRepository.STATUS_ON_HOLD);
  point.setName(model.getName());
  point.setSequence(model.getSequence());
  point.setNotes(model.getNotes());
  point.setControlFrequency(model.getControlFrequency());
  point.setControlPointType(model.getControlPointType());

  for (QualityMeasuringPoint measuringPoint : model.getMeasuringPointList()) {
    measuringPoint = Beans.get(QualityMeasuringPointRepository.class).copy(measuringPoint, true);
    point.addMeasuringPointListItem(measuringPoint);
  }

  point.setControlPointDate(qualityControl.getStartDate());

  controlPointRepo.save(point);

protected void storeCustomsCodesForStockMove(StockMove stockMove) throws AxelorException {

  Long stockMoveId = stockMove.getId();
  Query<StockMoveLine> query = getStockMoveLineQuery(stockMoveId);

  BatchProcessorHelper.of()
      .<StockMoveLine, AxelorException>forEachByQuery(
          query, stockMoveLineService::storeCustomsCodes);
